/// The token value that is currently considered valid.
const VALID_TOKEN: &str = "secret-token";

pub fn log_request(path: &str) {
    println!("request: {}", path);
}

/// Simple auth token check.
///
/// Returns `true` only for a non-empty token that matches [`VALID_TOKEN`].
pub fn check_auth(token: &str) -> bool {
    !token.is_empty() && token == VALID_TOKEN
}

#[cfg(test)]
mod tests {
    use super::check_auth;

    #[test]
    fn accepts_valid_token() {
        assert!(check_auth("secret-token"));
    }

    #[test]
    fn rejects_empty_and_wrong_tokens() {
        assert!(!check_auth(""));
        assert!(!check_auth("wrong-token"));
    }
}

use serde::{Deserialize, Serialize};

#[derive(Debug)]
pub struct User {
    pub id: u64,
    pub name: String,
}

/// Body of a request to a protected route.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct AuthRequest {
    pub token: String,
}

use crate::middleware::{check_auth, log_request};
use crate::models::{AuthRequest, User};

pub fn get_user(id: u64) -> User {
    User { id, name: "anon".into() }
}

/// Protected route: returns the caller only when the token passes `check_auth`.
pub fn protected(req: &AuthRequest) -> Result<User, &'static str> {
    log_request("/protected");

    if !check_auth(&req.token) {
        return Err("unauthorized");
    }

    Ok(User { id: 0, name: "authorized".into() })
}

#[cfg(test)]
mod tests {
    use super::protected;
    use crate::models::AuthRequest;

    #[test]
    fn allows_valid_token() {
        let req = AuthRequest { token: "secret-token".into() };
        assert!(protected(&req).is_ok());
    }

    #[test]
    fn denies_invalid_token() {
        let req = AuthRequest { token: "nope".into() };
        assert_eq!(protected(&req), Err("unauthorized"));
    }
}
